function drawAsteroids() {
    // Neon asteroids with glow and gradient
    asteroids.forEach(a => {
      const grad = ctx.createRadialGradient(
        a.x + a.w / 2,
        a.y + a.h / 2,
        a.w * 0.1,
        a.x + a.w / 2,
        a.y + a.h / 2,
        a.w / 2
      );
      grad.addColorStop(0, '#ff0');
      grad.addColorStop(1, '#f0f');
      ctx.save();
      ctx.shadowBlur = 10;
      ctx.shadowColor = '#f0f';
      ctx.fillStyle = grad;
      ctx.fillRect(a.x, a.y, a.w, a.h);
      ctx.restore();
    });
  }

